using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
// Opt-in CLI-only checks. Ordinary play never instantiates this runner.
public sealed class S3BuildVerification:MonoBehaviour
{
    static string phase,output;static bool full;readonly List<string> lines=new(),errors=new();Keyboard kb;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Initialize(){if(Application.isEditor)return;var a=Environment.GetCommandLineArgs();full=Array.IndexOf(a,"-s3-full-verify")>=0;int i=Array.IndexOf(a,full?"-s3-full-verify":"-s3-verify");if(i<0||i+2>=a.Length)return;phase=a[i+1];output=Path.GetFullPath(a[i+2]);if(File.Exists(output)){Application.Quit(2);return;}var go=new GameObject("S3 build verification");DontDestroyOnLoad(go);go.AddComponent<S3BuildVerification>();}
    PlayerInputReader Player=>RoomSession.Instance.Player;Rigidbody2D Body=>Player.GetComponent<Rigidbody2D>();PlayerMotor Motor=>Player.GetComponent<PlayerMotor>();
    void Awake()=>Application.logMessageReceived+=Log;
    void Log(string m,string s,LogType t){if(t is LogType.Error or LogType.Exception or LogType.Assert)errors.Add(m+s);}
    void Check(bool ok,string m){if(!ok)throw new Exception(m);lines.Add("PASS: "+m);}
    IEnumerator Start(){InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;kb=InputSystem.AddDevice<Keyboard>();QualitySettings.vSyncCount=0;Application.targetFrameRate=60;var stack=new Stack<IEnumerator>();stack.Push(Tests());bool fail=false;while(stack.Count>0&&!fail){object next=null;try{if(!stack.Peek().MoveNext()){stack.Pop();continue;}next=stack.Peek().Current;}catch(Exception e){fail=true;lines.Add("FAIL: "+e);}if(next is IEnumerator child)stack.Push(child);else if(!fail)yield return next;}Application.logMessageReceived-=Log;InputSystem.RemoveDevice(kb);fail|=errors.Count>0;lines.AddRange(errors);lines.Insert(0,(fail?"FAIL":"PASS")+" Windows exe "+phase+" Unity="+Application.unityVersion);lines.Add("Error/Exception/Assert "+errors.Count);lines.Add("NOTE: direct placement and prescribed inputs; no navigation robot; isolated save slot");Directory.CreateDirectory(Path.GetDirectoryName(output));File.WriteAllLines(output,lines);Application.Quit(fail?1:0);}
    IEnumerator Keys(params Key[] keys){InputSystem.QueueStateEvent(kb,new KeyboardState(keys));yield return null;yield return new WaitForFixedUpdate();}
    IEnumerator Tap(Key key){yield return Keys(key);yield return Keys();}
    IEnumerator Until(Func<bool> condition){double end=Time.realtimeSinceStartupAsDouble+5;while(!condition()){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("runtime timeout");yield return null;}}
    void Place(Vector2 p){Player.ClearTransientInput();Player.transform.position=p;Body.position=p;Body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
    IEnumerator Ready(){yield return Until(()=>RoomSession.Instance?.Player!=null&&RoomSession.Instance.CurrentRoomId!=null&&!RoomSession.Instance.Transitioning&&!RoomSession.Instance.Respawning);yield return new WaitForSeconds(.1f);}
    IEnumerator ExitTo(string target){RoomExit exit=null;foreach(var e in FindObjectsByType<RoomExit>(FindObjectsSortMode.None))if(e.destinationRoomId==target)exit=e;Check(exit!=null&&exit.enabled,"door exists to "+target);string id=exit.destinationSpawnId;Place(exit.GetComponent<BoxCollider2D>().bounds.center);yield return new WaitForFixedUpdate();yield return null;yield return Ready();Check(RoomSession.Instance.CurrentRoomId==target,"physical door transition "+target);var room=FindFirstObjectByType<RoomDefinition>();Check(room.TryGetSpawn(id,out var spawn)&&Vector2.Distance(Body.position,spawn.transform.position)<.2f,"safe spawn "+target+"/"+id);}
    IEnumerator TouchCP(string id){var cp=FindFirstObjectByType<Checkpoint>();Check(cp!=null&&cp.checkpointId==id,"checkpoint "+id);Place(cp.transform.position);yield return new WaitForSeconds(.15f);Check(RoomSession.Instance.CheckpointId==id,"physical activation "+id);}
    IEnumerator Death(string cp){double started=Time.realtimeSinceStartupAsDouble;Check(RoomSession.Instance.Die(),"death accepted");yield return Ready();Check(RoomSession.Instance.CheckpointId==cp&&Player.GetComponent<PlayerHealth>().HP==5,"checkpoint death return "+cp);lines.Add($"MEASURE death->control={Time.realtimeSinceStartupAsDouble-started:F3}s");}
    IEnumerator Tests(){yield return new WaitForSecondsRealtime(.3f);var menu=FindFirstObjectByType<SaveMenu>();Check(menu!=null&&SceneManager.GetActiveScene().name=="Menu","exe starts in Menu");
        if(full&&phase=="continue")
        {
            Check(menu.CanContinue,"Continue enabled after first full process");yield return Tap(UnityEngine.InputSystem.Key.Z);yield return Ready();
            Check(RoomSession.Instance.CurrentRoomId=="C04"&&RoomSession.Instance.CheckpointId=="CP-C04","second process Continue maps CP-C04");
            Check(Motor.hasDoubleJump&&Player.GetComponent<PlayerDash>().hasDash,"both abilities survive full process exit");
            var room=FindFirstObjectByType<RoomDefinition>();Check(room.TryGetSpawn("CP-C04",out var spawn)&&Vector2.Distance(Body.position,spawn.transform.position)<.2f,"CP-C04 safe Continue spawn");
            yield return Death("CP-C04");yield return ExitTo("C03");yield return ExitTo("C02");yield return ExitTo("C01");yield return ExitTo("B05");yield return ExitTo("B01");yield return ExitTo("B02");yield return ExitTo("B03");yield return ExitTo("B04");yield return new WaitForSeconds(.2f);
            Check(FindFirstObjectByType<DoubleJumpPickup>()==null,"Continue ownership suppresses Double Jump pickup");yield return Death("CP-C04");Check(RoomSession.Instance.CurrentRoomId=="C04","long-distance saved checkpoint return");yield break;
        }
        if(phase=="continue"){Check(menu.CanContinue,"Continue enabled after previous process acquisition");yield return Tap(UnityEngine.InputSystem.Key.Z);yield return Ready();Check(RoomSession.Instance.CurrentRoomId=="B01"&&RoomSession.Instance.CheckpointId=="CP-B01","second process Continue maps CP-B01");Check(Motor.hasDoubleJump&&Player.GetComponent<PlayerDash>().hasDash,"both abilities survive process exit/Continue");var room=FindFirstObjectByType<RoomDefinition>();Check(room.TryGetSpawn("CP-B01",out var spawn)&&Vector2.Distance(Body.position,spawn.transform.position)<.2f,"Continue safe checkpoint position");yield return Death("CP-B01");yield return ExitTo("B02");yield return ExitTo("B03");yield return ExitTo("B04");yield return new WaitForSeconds(.2f);Check(FindFirstObjectByType<DoubleJumpPickup>()==null,"loaded ownership suppresses pickup");yield break;}
        Check(phase=="route","known runtime phase");Check(!menu.CanContinue,"fresh isolated save has Continue disabled");yield return Tap(UnityEngine.InputSystem.Key.Z);yield return Ready();Check(RoomSession.Instance.CurrentRoomId=="A01"&&!Motor.hasDoubleJump&&!Player.GetComponent<PlayerDash>().hasDash,"new game abilities false");yield return TouchCP("CP-A01");yield return ExitTo("A02");Place(FindFirstObjectByType<KillZone>().transform.position);yield return new WaitForFixedUpdate();yield return null;yield return Ready();Check(RoomSession.Instance.CurrentRoomId=="A01"&&Player.GetComponent<PlayerHealth>().HP==5,"physical A02 hazard returns CP-A01");yield return ExitTo("A02");yield return ExitTo("A03");yield return TouchCP("CP-A03");yield return Death("CP-A03");yield return ExitTo("A04");yield return ExitTo("A05");Place(FindFirstObjectByType<DashPickup>().transform.position);yield return new WaitForFixedUpdate();yield return null;Check(Player.GetComponent<PlayerDash>().hasDash,"A05 physical Dash acquisition");yield return ExitTo("A04");yield return ExitTo("A03");yield return ExitTo("B01");yield return TouchCP("CP-B01");yield return ExitTo("A03");yield return ExitTo("B01");yield return ExitTo("B02");yield return ExitTo("B03");yield return ExitTo("B04");Check(!Motor.hasDoubleJump,"B04 unowned on first entry");Place(new Vector2(6,6));yield return new WaitForSeconds(.15f);int count=Motor.DoubleJumpsPerformed;yield return Tap(UnityEngine.InputSystem.Key.Z);Check(Motor.DoubleJumpsPerformed==count,"pre-acquisition additional jump unavailable");Place(FindFirstObjectByType<DoubleJumpPickup>().transform.position);yield return new WaitForFixedUpdate();yield return null;Check(Motor.hasDoubleJump&&RoomSession.Instance.CheckpointId=="CP-B01","B04 physical pickup preserves checkpoint");yield return Keys();Place(new Vector2(19.1f,3.81f));yield return new WaitForSeconds(.2f);yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.Z);yield return new WaitForSeconds(.26f);yield return Keys(UnityEngine.InputSystem.Key.RightArrow);yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.Z);yield return new WaitForSeconds(.65f);yield return Keys();yield return new WaitForSeconds(.3f);var high=GameObject.Find("B04_PracticeHigh").GetComponent<BoxCollider2D>();Check(Motor.Grounded&&Body.position.x>=23&&Mathf.Abs(Body.position.y-.8f-high.bounds.max.y)<.08f,"exe double jump lands on corrected High");lines.Add($"MEASURE corrected High top={high.bounds.max.y:F3} feet={Body.position.y-.8f:F3}");yield return ExitTo("B03");yield return ExitTo("B02");yield return ExitTo("B01");yield return ExitTo("B05");yield return ExitTo("B01");yield return ExitTo("B02");yield return ExitTo("B03");yield return ExitTo("B04");yield return new WaitForSeconds(.15f);Check(FindFirstObjectByType<DoubleJumpPickup>()==null,"B04 reentry owned pickup absent");yield return Death("CP-B01");Check(RoomSession.Instance.CurrentRoomId=="B01"&&Motor.hasDoubleJump,"B04 death returns CP-B01 retaining ability");Check(ProgressSave.TryLoad(out var data)&&data.dash&&data.doubleJump&&data.checkpointId=="CP-B01","disk save contains abilities and valid CP");yield return ExitTo("B05");yield return ExitTo("B01");yield return ExitTo("A03");yield return ExitTo("A02");yield return ExitTo("A01");Check(Motor.hasDoubleJump,"all graph doors traversed both ways with ownership retained");lines.Add("NOTE: exit this process, launch Continue verification separately");
        if(full)yield return FullRoute();
    }
    IEnumerator FullRoute()
    {
        yield return ExitTo("A02");yield return ExitTo("A03");yield return ExitTo("B01");yield return ExitTo("B05");yield return ExitTo("C01");yield return TouchCP("CP-C01");
        yield return ExitTo("C02");yield return Death("CP-C01");Check(RoomSession.Instance.CurrentRoomId=="C01","C02 death restores CP-C01 in exe");
        yield return ExitTo("C02");yield return Keys();Place(new Vector2(9.3f,3.81f));yield return new WaitForSeconds(.2f);
        yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.Z);yield return new WaitForSeconds(.28f);yield return Keys(UnityEngine.InputSystem.Key.RightArrow);yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.Z);yield return new WaitForSeconds(.67f);yield return Keys();yield return new WaitForSeconds(.15f);
        Check(Motor.Grounded&&Body.position.x>=12&&Body.position.x<=16.4f&&Mathf.Abs(Body.position.y-7.6f)<.08f,"exe C02 Start double jump lands High1");
        Place(new Vector2(15.3f,7.61f));yield return new WaitForSeconds(.2f);yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.Z);yield return new WaitForSeconds(.28f);yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.Z,UnityEngine.InputSystem.Key.C);yield return new WaitForSeconds(.62f);yield return Keys();yield return new WaitForSeconds(.15f);
        Check(Motor.Grounded&&Body.position.x>=21&&Body.position.x<=25.4f&&Mathf.Abs(Body.position.y-7.6f)<.08f,"exe C02 jump plus dash lands High2");
        yield return ExitTo("C03");yield return ExitTo("C04");yield return TouchCP("CP-C04");yield return ExitTo("C03");yield return Death("CP-C04");Check(RoomSession.Instance.CurrentRoomId=="C04","exe C03 death restores CP-C04");
        yield return ExitTo("C03");yield return ExitTo("C02");yield return ExitTo("C01");yield return ExitTo("B05");yield return ExitTo("C01");yield return ExitTo("C02");yield return ExitTo("C03");yield return ExitTo("C04");
        Check(ProgressSave.TryLoad(out var data)&&data.checkpointId=="CP-C04"&&data.dash&&data.doubleJump,"full route persisted both abilities and CP-C04");
        var blocked=Array.Find(FindObjectsByType<RoomExit>(FindObjectsSortMode.None),e=>e.destinationRoomId=="C06");Check(blocked!=null&&!blocked.enabled,"C06 door disabled; unsuccessful stages excluded safely");
        Check(SceneManager.sceneCount==1&&FindObjectsByType<PlayerInputReader>(FindObjectsSortMode.None).Length==1,"single scene and persistent player after all doors");
        lines.Add("S3-09 BLOCKED / S3-10 SKIPPED: boss, Ending, Quit and Pause title not implemented or tested. Physical pad/natural route play time not tested.");
    }
}
